{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import * as readline from 'readline'

const args = process.argv.slice(2)

if (args.length !== 1 || !['values', 'deps'].includes(args[0])) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const mode = args[0]

// Read stdin
async function main() {
  const rl = readline.createInterface({
    input: process.stdin,
    output: undefined,
    terminal: false
  })

  const lines = []
  for await (const line of rl) {
    lines.push(line)
  }

  try {
    const sheet = parseSheet(lines)
    if (mode === 'values') {
      outputValues(sheet)
    } else {
      outputDeps(sheet)
    }
    process.exit(0)
  } catch (e) {
    process.stderr.write(e.message + '\n')
    process.exit(2)
  }
}

// Parse sheet from lines
function parseSheet(lines) {
  const cells = new Map() // address -> { content, isFormula }

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    const line = lines[lineNum]
    const trimmed = line.replace(/^[ \t]+/, '')

    // Skip empty lines and comments
    if (!trimmed || trimmed[0] === '#') continue

    // Parse address and content
    const match = trimmed.match(/^([A-Za-z]{1,2}\d{1,3})[ \t]+(.*)$/)
    if (!match) continue

    const address = match[1].toUpperCase()
    const content = match[2]

    // Validate address
    if (!isValidAddress(address)) {
      throw new Error(`error: line ${lineNum + 1}: invalid cell address ${match[1]}`)
    }

    // Check for duplicate
    if (cells.has(address)) {
      throw new Error(`error: line ${lineNum + 1}: cell ${address} is declared twice`)
    }

    const isFormula = content.startsWith('=')
    cells.set(address, {
      content: isFormula ? content.slice(1) : content,
      isFormula
    })
  }

  return cells
}

function isValidAddress(addr) {
  const match = addr.match(/^([A-Z]{1,2})(\d{1,3})$/)
  if (!match) return false

  const col = match[1]
  const row = parseInt(match[2], 10)

  // Column check
  if (col.length === 1) {
    if (col < 'A' || col > 'Z') return false
  } else {
    if (col < 'AA' || col > 'ZZ') return false
  }

  // Row check
  if (row < 1 || row > 999) return false

  return true
}

function outputValues(cells) {
  const evaluator = new Evaluator(cells)
  const sorted = Array.from(cells.keys()).sort((a, b) => {
    const colA = parseAddress(a).col
    const colB = parseAddress(b).col
    const rowA = parseAddress(a).row
    const rowB = parseAddress(b).row

    if (colA !== colB) return colA.localeCompare(colB)
    return rowA - rowB
  })

  for (const addr of sorted) {
    const value = evaluator.evaluate(addr)
    const formatted = formatValue(value)
    process.stdout.write(`${addr}=${formatted}\n`)
  }
}

function outputDeps(cells) {
  const evaluator = new Evaluator(cells)
  const sorted = Array.from(cells.keys()).sort((a, b) => {
    const colA = parseAddress(a).col
    const colB = parseAddress(b).col
    const rowA = parseAddress(a).row
    const rowB = parseAddress(b).row

    if (colA !== colB) return colA.localeCompare(colB)
    return rowA - rowB
  })

  for (const addr of sorted) {
    const deps = evaluator.getDeps(addr)
    const sorted_deps = deps.sort((a, b) => {
      const colA = parseAddress(a).col
      const colB = parseAddress(b).col
      const rowA = parseAddress(a).row
      const rowB = parseAddress(b).row

      if (colA !== colB) return colA.localeCompare(colB)
      return rowA - rowB
    })

    const depStr = sorted_deps.length > 0 ? ' ' + sorted_deps.join(' ') : ''
    process.stdout.write(`${addr}:${depStr}\n`)
  }
}

function parseAddress(addr) {
  const match = addr.match(/^([A-Z]{1,2})(\d+)$/)
  return { col: match[1], row: parseInt(match[2], 10) }
}

function formatValue(value) {
  if (value && value.type === 'error') {
    return value.value
  }
  if (value && value.type === 'boolean') {
    return value.value ? 'TRUE' : 'FALSE'
  }
  if (value && value.type === 'number') {
    return formatNumber(value.value)
  }
  if (value && value.type === 'text') {
    return value.value
  }
  // Default to 0
  return '0'
}

function formatNumber(num) {
  if (!isFinite(num)) {
    return '#DIV/0!'
  }
  // Round to 10 significant digits
  const str = num.toPrecision(10)
  // Remove trailing zeros after decimal point
  let formatted = parseFloat(str).toString()
  // Handle scientific notation for very small/large numbers
  if (formatted.includes('e')) {
    formatted = num.toString()
  }
  return formatted
}

class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.cache = new Map()
    this.computing = new Set()
  }

  evaluate(addr) {
    if (!isValidAddress(addr)) {
      return { type: 'error', value: '#REF!' }
    }

    if (this.cache.has(addr)) {
      return this.cache.get(addr)
    }

    if (this.computing.has(addr)) {
      return { type: 'error', value: '#CYCLE!' }
    }

    this.computing.add(addr)

    let result
    if (this.cells.has(addr)) {
      const cell = this.cells.get(addr)
      if (cell.isFormula) {
        try {
          result = this.evaluateFormula(cell.content, addr)
        } catch (e) {
          result = { type: 'error', value: '#ERR!' }
        }
      } else {
        result = this.parseLiteral(cell.content)
      }
    } else {
      result = { type: 'number', value: 0 }
    }

    this.computing.delete(addr)
    this.cache.set(addr, result)
    return result
  }

  evaluateFormula(formula, originAddr) {
    const parser = new Parser(formula, this)
    const ast = parser.parse()
    return this.evaluateAST(ast, originAddr)
  }

  evaluateAST(ast, originAddr) {
    if (ast.type === 'number') {
      return { type: 'number', value: ast.value }
    }
    if (ast.type === 'text') {
      return { type: 'text', value: ast.value }
    }
    if (ast.type === 'boolean') {
      return { type: 'boolean', value: ast.value }
    }
    if (ast.type === 'error') {
      return { type: 'error', value: ast.value }
    }
    if (ast.type === 'cell') {
      const cellAddr = ast.value
      if (!isValidAddress(cellAddr)) {
        return { type: 'error', value: '#REF!' }
      }
      return this.evaluate(cellAddr)
    }
    if (ast.type === 'range') {
      // Ranges should not appear outside function calls
      return { type: 'error', value: '#ERR!' }
    }
    if (ast.type === 'binary') {
      return this.evaluateBinary(ast, originAddr)
    }
    if (ast.type === 'unary') {
      return this.evaluateUnary(ast, originAddr)
    }
    if (ast.type === 'call') {
      return this.evaluateCall(ast, originAddr)
    }
    return { type: 'error', value: '#ERR!' }
  }

  evaluateBinary(ast, originAddr) {
    const left = this.evaluateAST(ast.left, originAddr)
    const right = this.evaluateAST(ast.right, originAddr)

    // Error propagation: left error wins
    if (left.type === 'error') return left
    if (right.type === 'error') return right

    const op = ast.operator

    if (op === '+' || op === '-' || op === '*' || op === '/') {
      return this.evaluateArithmetic(left, right, op)
    }

    if (op === '^') {
      const leftNum = this.toNumber(left)
      const rightNum = this.toNumber(right)
      if (leftNum.type === 'error') return leftNum
      if (rightNum.type === 'error') return rightNum
      const result = Math.pow(leftNum.value, rightNum.value)
      if (!isFinite(result)) {
        return { type: 'error', value: '#DIV/0!' }
      }
      return { type: 'number', value: result }
    }

    if (['=', '<>', '<', '<=', '>', '>='].includes(op)) {
      return this.evaluateComparison(left, right, op)
    }

    return { type: 'error', value: '#ERR!' }
  }

  evaluateUnary(ast, originAddr) {
    const operand = this.evaluateAST(ast.operand, originAddr)
    if (operand.type === 'error') return operand

    const op = ast.operator
    if (op === '-') {
      const num = this.toNumber(operand)
      if (num.type === 'error') return num
      return { type: 'number', value: -num.value }
    }
    if (op === '+') {
      const num = this.toNumber(operand)
      if (num.type === 'error') return num
      return num
    }
    return { type: 'error', value: '#ERR!' }
  }

  evaluateCall(ast, originAddr) {
    const name = ast.name.toUpperCase()
    const args = ast.arguments

    if (name === 'IF') {
      if (args.length !== 3) return { type: 'error', value: '#ERR!' }
      const condition = this.evaluateAST(args[0], originAddr)
      if (condition.type === 'error') return condition

      const condValue = this.toBoolean(condition)
      if (condValue) {
        return this.evaluateAST(args[1], originAddr)
      } else {
        return this.evaluateAST(args[2], originAddr)
      }
    }

    if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS'].includes(name)) {
      if (name === 'ABS') {
        if (args.length !== 1) return { type: 'error', value: '#ERR!' }
        const values = this.expandArguments(args[0], originAddr)
        if (values.type === 'error') return values
        if (values.length !== 1) return { type: 'error', value: '#ERR!' }
        const num = this.toNumber(values[0])
        if (num.type === 'error') return num
        return { type: 'number', value: Math.abs(num.value) }
      }

      if (args.length < 1) return { type: 'error', value: '#ERR!' }

      // Collect all values from all arguments
      const allValues = []
      for (const arg of args) {
        const values = this.expandArguments(arg, originAddr)
        if (values.type === 'error') return values
        allValues.push(...values)
      }

      if (name === 'COUNT') {
        let count = 0
        for (const val of allValues) {
          if (val.type === 'number') count++
        }
        return { type: 'number', value: count }
      }

      // For SUM, MIN, MAX, AVG - convert to numbers
      const numbers = []
      for (const val of allValues) {
        const num = this.toNumber(val)
        if (num.type === 'error') return num
        numbers.push(num.value)
      }

      if (name === 'SUM') {
        const sum = numbers.reduce((a, b) => a + b, 0)
        if (!isFinite(sum)) return { type: 'error', value: '#DIV/0!' }
        return { type: 'number', value: sum }
      }

      if (name === 'MIN') {
        if (numbers.length === 0) return { type: 'number', value: 0 }
        const min = Math.min(...numbers)
        if (!isFinite(min)) return { type: 'error', value: '#DIV/0!' }
        return { type: 'number', value: min }
      }

      if (name === 'MAX') {
        if (numbers.length === 0) return { type: 'number', value: 0 }
        const max = Math.max(...numbers)
        if (!isFinite(max)) return { type: 'error', value: '#DIV/0!' }
        return { type: 'number', value: max }
      }

      if (name === 'AVG') {
        if (numbers.length === 0) return { type: 'number', value: 0 }
        const sum = numbers.reduce((a, b) => a + b, 0)
        const avg = sum / numbers.length
        if (!isFinite(avg)) return { type: 'error', value: '#DIV/0!' }
        return { type: 'number', value: avg }
      }
    }

    return { type: 'error', value: '#NAME?' }
  }

  expandArguments(arg, originAddr) {
    if (arg.type === 'range') {
      // Expand range
      const from = arg.from
      const to = arg.to
      if (!isValidAddress(from) || !isValidAddress(to)) {
        return { type: 'error', value: '#REF!' }
      }

      const fromParsed = parseAddress(from)
      const toParsed = parseAddress(to)

      const results = []
      for (const addr of this.rangeToAddresses(fromParsed, toParsed)) {
        results.push(this.evaluate(addr))
      }
      return results
    }

    const val = this.evaluateAST(arg, originAddr)
    return [val]
  }

  rangeToAddresses(from, to) {
    const fromCol = colToNumber(from.col)
    const toCol = colToNumber(to.col)
    const minCol = Math.min(fromCol, toCol)
    const maxCol = Math.max(fromCol, toCol)
    const minRow = Math.min(from.row, to.row)
    const maxRow = Math.max(from.row, to.row)

    const addrs = []
    for (let c = minCol; c <= maxCol; c++) {
      for (let r = minRow; r <= maxRow; r++) {
        addrs.push(numberToCol(c) + r)
      }
    }
    return addrs
  }

  evaluateArithmetic(left, right, op) {
    const leftNum = this.toNumber(left)
    const rightNum = this.toNumber(right)

    if (leftNum.type === 'error') return leftNum
    if (rightNum.type === 'error') return rightNum

    const l = leftNum.value
    const r = rightNum.value

    let result
    if (op === '+') {
      result = l + r
    } else if (op === '-') {
      result = l - r
    } else if (op === '*') {
      result = l * r
    } else if (op === '/') {
      if (r === 0) {
        return { type: 'error', value: '#DIV/0!' }
      }
      result = l / r
    }

    if (!isFinite(result)) {
      return { type: 'error', value: '#DIV/0!' }
    }

    return { type: 'number', value: result }
  }

  evaluateComparison(left, right, op) {
    let cmp
    if (left.type === 'number' && right.type === 'number') {
      const l = left.value
      const r = right.value
      if (l < r) cmp = -1
      else if (l > r) cmp = 1
      else cmp = 0
    } else if (left.type === 'text' && right.type === 'text') {
      cmp = left.value.localeCompare(right.value)
    } else if (left.type === 'boolean' && right.type === 'boolean') {
      const l = left.value ? 1 : 0
      const r = right.value ? 1 : 0
      if (l < r) cmp = -1
      else if (l > r) cmp = 1
      else cmp = 0
    } else {
      // Different types: number < text < boolean
      const order = { number: 0, text: 1, boolean: 2 }
      const leftOrder = order[left.type] ?? 3
      const rightOrder = order[right.type] ?? 3
      if (leftOrder < rightOrder) cmp = -1
      else if (leftOrder > rightOrder) cmp = 1
      else cmp = 0
    }

    let result
    if (op === '=') result = cmp === 0
    else if (op === '<>') result = cmp !== 0
    else if (op === '<') result = cmp < 0
    else if (op === '<=') result = cmp <= 0
    else if (op === '>') result = cmp > 0
    else if (op === '>=') result = cmp >= 0

    return { type: 'boolean', value: result }
  }

  toNumber(val) {
    if (val.type === 'number') return val
    if (val.type === 'boolean') {
      return { type: 'number', value: val.value ? 1 : 0 }
    }
    if (val.type === 'text') {
      return { type: 'error', value: '#VALUE!' }
    }
    if (val.type === 'error') return val
    return { type: 'error', value: '#VALUE!' }
  }

  toBoolean(val) {
    if (val.type === 'boolean') return val.value
    if (val.type === 'number') return val.value !== 0
    return false
  }

  parseLiteral(content) {
    if (!content) {
      return { type: 'number', value: 0 }
    }

    // Check for error tokens
    const errorTokens = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
    if (errorTokens.includes(content)) {
      return { type: 'error', value: content }
    }

    // Check for boolean
    if (content === 'TRUE') {
      return { type: 'boolean', value: true }
    }
    if (content === 'FALSE') {
      return { type: 'boolean', value: false }
    }

    // Check for number
    if (/^-?\d+(\.\d+)?$/.test(content)) {
      const num = parseFloat(content)
      return { type: 'number', value: num }
    }

    // Text
    return { type: 'text', value: content }
  }

  getDeps(addr) {
    if (!this.cells.has(addr)) {
      return []
    }

    const cell = this.cells.get(addr)
    if (!cell.isFormula) {
      return []
    }

    try {
      const parser = new Parser(cell.content, this)
      const ast = parser.parse()
      const deps = this.extractDeps(ast)
      return deps
    } catch (e) {
      return []
    }
  }

  extractDeps(ast) {
    const deps = new Set()

    function visit(node) {
      if (!node) return
      if (node.type === 'cell') {
        const addr = node.value
        if (isValidAddress(addr)) {
          deps.add(addr)
        }
      } else if (node.type === 'range') {
        const from = node.from
        const to = node.to
        if (isValidAddress(from) && isValidAddress(to)) {
          const fromParsed = parseAddress(from)
          const toParsed = parseAddress(to)
          const addrs = new Evaluator(this.cells).rangeToAddresses(fromParsed, toParsed)
          addrs.forEach(a => deps.add(a))
        }
      } else if (node.type === 'binary') {
        visit(node.left)
        visit(node.right)
      } else if (node.type === 'unary') {
        visit(node.operand)
      } else if (node.type === 'call') {
        for (const arg of node.arguments) {
          visit(arg)
        }
      }
    }

    visit(ast)
    return Array.from(deps)
  }
}

class Parser {
  constructor(formula, evaluator) {
    this.formula = formula
    this.evaluator = evaluator
    this.pos = 0
  }

  parse() {
    const expr = this.parseComparison()
    this.skipWhitespace()
    if (this.pos < this.formula.length) {
      return { type: 'error', value: '#ERR!' }
    }
    return expr
  }

  parseComparison() {
    let left = this.parseAdditive()
    this.skipWhitespace()

    while (this.pos < this.formula.length) {
      if (this.peekOperator('=<>')) {
        const op = this.readOperator()
        const right = this.parseAdditive()
        left = { type: 'binary', operator: op, left, right }
      } else {
        break
      }
    }

    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()

    while (true) {
      this.skipWhitespace()
      if (this.peek() === '+' || this.peek() === '-') {
        const op = this.formula[this.pos++]
        const right = this.parseMultiplicative()
        left = { type: 'binary', operator: op, left, right }
      } else {
        break
      }
    }

    return left
  }

  parseMultiplicative() {
    let left = this.parseExponent()

    while (true) {
      this.skipWhitespace()
      if (this.peek() === '*' || this.peek() === '/') {
        const op = this.formula[this.pos++]
        const right = this.parseExponent()
        left = { type: 'binary', operator: op, left, right }
      } else {
        break
      }
    }

    return left
  }

  parseExponent() {
    let left = this.parseUnary()

    while (true) {
      this.skipWhitespace()
      if (this.peek() === '^') {
        this.pos++
        const right = this.parseExponent() // Right associative
        left = { type: 'binary', operator: '^', left, right }
      } else {
        break
      }
    }

    return left
  }

  parseUnary() {
    this.skipWhitespace()
    if (this.peek() === '-' || this.peek() === '+') {
      const op = this.formula[this.pos++]
      const operand = this.parseUnary()
      return { type: 'unary', operator: op, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    this.skipWhitespace()

    if (this.peek() === '(') {
      this.pos++
      const expr = this.parseComparison()
      this.skipWhitespace()
      if (this.peek() !== ')') {
        return { type: 'error', value: '#ERR!' }
      }
      this.pos++
      return expr
    }

    // Try to parse number
    const numMatch = this.formula.slice(this.pos).match(/^(\d+(\.\d+)?)/)
    if (numMatch) {
      this.pos += numMatch[0].length
      return { type: 'number', value: parseFloat(numMatch[0]) }
    }

    // Try to parse function call or cell/range
    const identMatch = this.formula.slice(this.pos).match(/^([A-Za-z_][A-Za-z0-9_]*)/)
    if (identMatch) {
      const ident = identMatch[1]
      this.pos += ident.length
      this.skipWhitespace()

      // Check if it's a function call
      if (this.peek() === '(') {
        this.pos++
        const args = []
        this.skipWhitespace()

        if (this.peek() !== ')') {
          while (true) {
            args.push(this.parseComparison())
            this.skipWhitespace()
            if (this.peek() === ',') {
              this.pos++
              this.skipWhitespace()
            } else if (this.peek() === ')') {
              break
            } else {
              return { type: 'error', value: '#ERR!' }
            }
          }
        }

        this.pos++ // consume )
        return { type: 'call', name: ident, arguments: args }
      }

      // Check if it's a range (address:address)
      const isCell = /^[A-Z]{1,2}\d{1,3}$/i.test(ident)
      if (isCell) {
        const addr = ident.toUpperCase()
        this.skipWhitespace()

        if (this.peek() === ':') {
          this.pos++
          this.skipWhitespace()
          const identMatch2 = this.formula.slice(this.pos).match(/^([A-Za-z]{1,2}\d{1,3})/)
          if (!identMatch2) {
            return { type: 'error', value: '#ERR!' }
          }
          const addr2 = identMatch2[1].toUpperCase()
          this.pos += identMatch2[0].length
          return { type: 'range', from: addr, to: addr2 }
        }

        return { type: 'cell', value: addr }
      }

      // It's a bare word - could be TRUE, FALSE, or a cell name (treated as cell)
      if (ident.toUpperCase() === 'TRUE') {
        return { type: 'boolean', value: true }
      }
      if (ident.toUpperCase() === 'FALSE') {
        return { type: 'boolean', value: false }
      }

      // Treat as cell address
      const normalizedIdent = ident.toUpperCase()
      if (!isValidAddress(normalizedIdent)) {
        return { type: 'error', value: '#ERR!' }
      }
      return { type: 'cell', value: normalizedIdent }
    }

    return { type: 'error', value: '#ERR!' }
  }

  peekOperator(chars) {
    const ch = this.peek()
    if (chars.includes(ch)) return true
    if (ch === '<' && (this.peekAhead(1) === '=' || this.peekAhead(1) === '>')) {
      return true
    }
    if (ch === '>' && this.peekAhead(1) === '=') {
      return true
    }
    return false
  }

  readOperator() {
    const ch = this.peek()
    if (ch === '<') {
      if (this.peekAhead(1) === '=') {
        this.pos += 2
        return '<='
      }
      if (this.peekAhead(1) === '>') {
        this.pos += 2
        return '<>'
      }
      this.pos++
      return '<'
    }
    if (ch === '>') {
      if (this.peekAhead(1) === '=') {
        this.pos += 2
        return '>='
      }
      this.pos++
      return '>'
    }
    if (ch === '=') {
      this.pos++
      return '='
    }
    return null
  }

  peek() {
    return this.formula[this.pos] || ''
  }

  peekAhead(n) {
    return this.formula[this.pos + n] || ''
  }

  skipWhitespace() {
    while (this.pos < this.formula.length && (this.formula[this.pos] === ' ' || this.formula[this.pos] === '\t')) {
      this.pos++
    }
