      return { type: 'error', value: '#ERR!' }
    }
    if (ast.type === 'binary') {
      return this.evaluateBinary(ast, originAddr)
    }
    if (ast.type === 'unary') {
      return this.evaluateUnary(ast, originAddr)
    }
    if (ast.type === 'call') {
