      }

      if (name === 'MIN') {
        if (numbers.length === 0) return { type: 'number', value: 0 }
        const min = Math.min(...numbers)
        if (!isFinite(min)) return { type: 'error', value: '#DIV/0!' }
        return { type: 'number', value: min }
      }

      if (name === 'MAX') {
        if (numbers.length === 0) return { type: 'number', value: 0 }
        const max = Math.max(...numbers)
        if (!isFinite(max)) return { type: 'error', value: '#DIV/0!' }
        return { type: 'number', value: max }
      }

      if (name === 'AVG') {
        if (numbers.length === 0) return { type: 'number', value: 0 }
        const sum = numbers.reduce((a, b) => a + b, 0)
        const avg = sum / numbers.length
        if (!isFinite(avg)) return { type: 'error', value: '#DIV/0!' }
