        return { type: 'call', name: ident, arguments: args }
      }

      // Check if it's a range (address:address)
      const isCell = /^[A-Z]{1,2}\d{1,3}$/i.test(ident)
      if (isCell) {
        const addr = ident.toUpperCase()
        this.skipWhitespace()

        if (this.peek() === ':') {
          this.pos++
          this.skipWhitespace()
          const identMatch2 = this.formula.slice(this.pos).match(/^([A-Za-z]{1,2}\d{1,3})/)
          if (!identMatch2) {
            return { type: 'error', value: '#ERR!' }
          }
          const addr2 = identMatch2[1].toUpperCase()
          this.pos += identMatch2[0].length
          return { type: 'range', from: addr, to: addr2 }
        }

        return { type: 'cell', value: addr }
      }

      // It's a bare word - could be TRUE, FALSE, or a cell name (treated as cell)
      if (ident.toUpperCase() === 'TRUE') {
        return { type: 'boolean', value: true }
      }
      if (ident.toUpperCase() === 'FALSE') {
