    }

    return { type: 'error', value: '#ERR!' }
  }

  peekOperator(chars) {
    const ch = this.peek()
    if (chars.includes(ch)) return true
    if (ch === '<' && (this.peekAhead(1) === '=' || this.peekAhead(1) === '>')) {
