  }

  peek() {
    return this.formula[this.pos] || ''
  }

  peekAhead(n) {
    return this.formula[this.pos + n] || ''
  }

  skipWhitespace() {
    while (this.pos < this.formula.length && (this.formula[this.pos] === ' ' || this.formula[this.pos] === '\t')) {
      this.pos++
    }
  }
}

function colToNumber(col) {
  if (col.length === 1) {
    return col.charCodeAt(0) - 'A'.charCodeAt(0)
  }
  return 26 + (col.charCodeAt(0) - 'A'.charCodeAt(0)) * 26 + (col.charCodeAt(1) - 'A'.charCodeAt(0))
}

function numberToCol(n) {
  if (n < 26) {
    return String.fromCharCode('A'.charCodeAt(0) + n)
  }
  const first = Math.floor((n - 26) / 26)
  const second = (n - 26) % 26
  return String.fromCharCode('A'.charCodeAt(0) + first) + String.fromCharCode('A'.charCodeAt(0) + second)
}

